import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  previewCardArrowClasses,
  previewCardBackdropClasses,
  previewCardPopupClasses,
  previewCardPortalClasses,
  previewCardPositionerClasses,
  previewCardRootClasses,
  previewCardTriggerClasses,
  previewCardViewportClasses,
} from "./view";

export {
  previewCardArrowClasses,
  previewCardBackdropClasses,
  previewCardPopupClasses,
  previewCardPortalClasses,
  previewCardPositionerClasses,
  previewCardRootClasses,
  previewCardTriggerClasses,
  previewCardViewportClasses,
} from "./view";

export type PreviewCardStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: PreviewCardStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  children: readonly (Html | string)[];
  onOpen: ParentMessage;
  open: boolean;
  classes?: string | undefined;
  style?: PreviewCardStyle | undefined;
}>;

export type PortalViewConfig = Readonly<{
  open: boolean;
  children: readonly Html[];
  classes?: string | undefined;
  style?: PreviewCardStyle | undefined;
}>;

export type BackdropViewConfig<ParentMessage> = Readonly<{
  onClose: ParentMessage;
  ariaLabel?: string | undefined;
  classes?: string | undefined;
  style?: PreviewCardStyle | undefined;
}>;

export type PositionerViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: PreviewCardStyle | undefined;
}>;

export type PopupViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: PreviewCardStyle | undefined;
}>;

export type ViewportViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: PreviewCardStyle | undefined;
}>;

export type ArrowViewConfig = Readonly<{
  classes?: string | undefined;
  style?: PreviewCardStyle | undefined;
}>;

const cn = (base: string, classes?: string): string =>
  [base, classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  classes,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Class(cn(previewCardRootClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const triggerView = <ParentMessage>({
  children,
  onOpen,
  open,
  classes,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.OnClick(onOpen),
      h.Attribute("aria-expanded", open ? "true" : "false"),
      h.Attribute("aria-haspopup", "dialog"),
      h.DataAttribute("open", open ? "true" : "false"),
      h.Class(cn(previewCardTriggerClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const portalView = <ParentMessage>({
  open,
  children,
  classes,
  style,
}: PortalViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.div([h.Class("hidden")], []);
  }

  return h.div(
    [
      h.Class(cn(previewCardPortalClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const backdropView = <ParentMessage>({
  onClose,
  ariaLabel = "Close preview card",
  classes,
  style,
}: BackdropViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.AriaLabel(ariaLabel),
      h.OnClick(onClose),
      h.Class(cn(previewCardBackdropClasses, classes)),
      h.Style(style ?? {}),
    ],
    []
  );
};

export const positionerView = <ParentMessage>({
  children,
  classes,
  style,
}: PositionerViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Class(cn(previewCardPositionerClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const popupView = <ParentMessage>({
  children,
  classes,
  style,
}: PopupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Role("dialog"),
      h.Class(cn(previewCardPopupClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const viewportView = <ParentMessage>({
  children,
  classes,
  style,
}: ViewportViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Class(cn(previewCardViewportClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const arrowView = <ParentMessage>({
  classes,
  style,
}: ArrowViewConfig = {}): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("aria-hidden", "true"),
      h.Class(cn(previewCardArrowClasses, classes)),
      h.Style(style ?? {}),
    ],
    []
  );
};

export const previewCardRootClasses = "relative inline-block";

export const previewCardTriggerClasses =
  "inline-flex items-center rounded-md font-medium text-accent-700 underline underline-offset-4 outline-none transition-colors hover:text-accent-800 focus:ring-2 focus:ring-accent-100";

export const previewCardPortalClasses = "contents";

export const previewCardBackdropClasses = "fixed inset-0 z-40 bg-transparent";

export const previewCardPositionerClasses =
  "absolute left-0 top-full z-50 mt-2";

export const previewCardPopupClasses =
  "w-80 rounded-lg border border-gray-200 bg-white p-4 shadow-lg";

export const previewCardViewportClasses = "grid gap-3";

export const previewCardArrowClasses =
  "absolute -top-1 left-8 size-3 rotate-45 border-l border-t border-gray-200 bg-white";

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as PreviewCardBasicExample from "../../examples/preview-card-basic/main";

describe("preview-card", () => {
  test("renders trigger and keeps popup closed by default", () => {
    const [model] = PreviewCardBasicExample.init();

    Scene.scene(
      {
        update: PreviewCardBasicExample.update,
        view: PreviewCardBasicExample.view,
      },
      Scene.with(model),
      Scene.expect(Scene.role("button", { name: "Base UI" })).toExist(),
      Scene.expect(Scene.role("dialog")).not.toExist()
    );
  });

  test("opens and closes controlled preview content", () => {
    const [model] = PreviewCardBasicExample.init();

    Scene.scene(
      {
        update: PreviewCardBasicExample.update,
        view: PreviewCardBasicExample.view,
      },
      Scene.with(model),
      Scene.click(Scene.role("button", { name: "Base UI" })),
      Scene.expect(Scene.role("dialog")).toExist(),
      Scene.expect(Scene.text("@base-ui")).toExist(),
      Scene.click(Scene.role("button", { name: "Close preview card" })),
      Scene.expect(Scene.role("dialog")).not.toExist()
    );
  });
});
